(function(){var D=window.AR_G8,S=window.AR_SIMPLIFY||(window.AR_SIMPLIFY={});if(!D)return;
Object.assign(D.B,{"tb1_def":"<div class='mh'>وصف مكان</div><p class='tx'>نص أدبيٌّ يهدف إلى وصفِ مكان معين بطريقة دقيقة، بحيث يمكن للقارئ أن يتخيله، ويشعر بأجوائه، ويستشعر خصائصه المميزة.</p>","tb1_steps":"<div class='mh'>خطواتُ كتابةِ مقالِ وصفِ مكان</div><ul class='dash'><li><b>أولًا:</b> اختر المكان الذي تريد وصفه بعناية، مع التأكد من معرفتك الجيدة له.</li><li><b>ثانيًا:</b> حدد الهدف من وصف المكان والانطباع الذي تريد إيصاله للقارئ.</li><li><b>ثالثًا:</b> اجمع التفاصيل والأوصاف المتعلقة بالمكان، ثم رتبها بطريقة منطقية.</li><li><b>رابعًا:</b> راجع النص للتأكد من تسلسل الأفكار ووضوح التعبير.</li></ul>","tb1_elems":"<div class='mh'>عناصر كتابة مقال وصف مكان</div><table class='plain'><tr><th>العنصر</th><th>بيانه</th></tr><tr><td><b>١- العنوان</b></td><td>يجب أن يكون جذابًا ومعبرًا عن طبيعة المكان، مثل: «حديقة الأحلام»، أو: «مكتبتي الصغيرة».</td></tr><tr><td><b>٢- المقدمة</b></td><td>وفيها تعريف مختصر بالمكان وأهميته، وسبب اختيار هذا المكان لوصفه.</td></tr><tr><td><b>٣- الموضوع</b></td><td>يشمل: ١- الأوصاف الخارجية: (الموقع، الشكل العام، المساحة). ٢- الأوصاف الداخلية: (التفاصيل، الأثاث، التصميم). ٣- الأوصاف الجسِّية: (الألوان، الأصوات، الروائح). ٤- وصف الجو العام للمكان: (هل المكان هادئ، صاخب، مريح...؟ هل المكان يُشعِرُنا بالفرح، الحماس، السكينة...؟ كيف يؤثر المكان على زوَّاره؟). ٥- وصف مظاهر الحركة والنشاط في المكان.</td></tr><tr><td><b>٤- الخاتمة</b></td><td>وفيها تلخيصٌ للانطباع العام عن المكان والمشاعر الشخصية تجاهه، ورسالة ختامية تترك أثرًا في نفس القارئ.</td></tr></table>","tb1_model":"<div class='mh'>نموذج تعريفي (مجاب عنه): مقال وصف مكان</div><p class='tx'><b>العنوان:</b> كنز مصر الحضاري الجديد</p><p class='tx'><b>المقدمة:</b> على مرمى البصر من أهرامات الجيزة يقف المتحف المصري الكبير شامخًا ليحتضن أعظم كنوز الحضارة المصرية القديمة، ويحكي للعالم قصة حضارتنا العظيمة، ويعدُّ هذا المتحف منارة ثقافية تضيء طريق المستقبل بنور الماضي المجيد.</p><p class='tx'><b>الأوصاف الخارجية:</b> وتبلغ مساحة المتحف أكثر من ٣٠٠ ألف متر مربع، ويبدو المتحف من الخارج كتحفة معمارية حديثة، وتُحيط به حدائق شاسعة، تضم الكثير من النباتات والنخيل.</p><p class='tx'><b>الأوصاف الداخلية:</b> وعند دخول المتحف، يقابلك البهو العظيم الذي يأسر الأنفاس بسقفه العالي وأعمدته الرخامية الضخمة. ويضم المتحف صالات عرض داخلية متعددة، و١٩ معملًا، وتضاء القطع الأثرية بإضاءة خاصة تبرز جمالها وتفاصيلها الدقيقة، وتعكس الأرضيات المصنوعة من الرخام المصقول الأضواء الناعمة، وتُزَيِّنُ الجدران بلوحات جدارية تحكي تاريخ مصر عبر العصور.</p><p class='tx'><b>الأوصاف الحسِّية:</b> تنتشر في أرجاء المتحف رائحة التاريخ المهيبة والتي تشهد على عظمة حضارتنا المصرية، ويسود المكان هدوء، لا يزيله سوى همسات الزائرين وأصوات أقدامهم الخافتة على الأرضيات الرخامية. وعندما تنعكس الأضواء على القطع الذهبية الفرعونية، تشع في المكان ألوان ساحرة.</p><p class='tx'><b>الجو العام للمكان:</b> ويثير المتحف المصري في نفوس زائريه مشاعر الهيبة والجلال والدهشة والإعجاب، ويترك في قلب كل زائر أثرًا لا يُنسى من جمال التراث وعظمة حضارتنا المصرية القديمة.</p><p class='tx'><b>وصف مظاهر الحركة والنشاط في المكان:</b> وفي أروقة المتحف، يتحرك الزائرون بخطًى متأنية، ويتوقفون طويلًا أمام كل قطعة أثرية ليتأملوا تفاصيلها ويقرءوا تاريخها، ويشرح المرشدون السياحيون بحماس وفخر قصص الملوك القدماء، بينما يلتقط السياح الصور التذكارية بشوق ومتعة.</p><p class='tx'><b>الخاتمة:</b> ويعد المتحف المصري الكبير رمزًا لعظمة الحضارة المصرية، ويقدم للعالم صورة مشرقة عنها. وعندما تقف في رحابه نشعر بالفخر الذي يملأ قلوبنا.</p>","tb1_model_q":"<div class='mh'>بعد قراءة النموذج التعريفي، أجب عمَّا يأتي</div><ul class='dash'><li>(أ) ما العنوان الذي اختاره الكاتب لمقاله؟ وما الذي يميزه؟</li><li>(ب) وضِّحْ سبب اختيار الكاتب لهذا المكان كي يصفَهُ.</li><li>(ج) حدد العناصر التي اشتمل عليها الوصف الخارجي للمتحف.</li><li>(د) أشار الكاتب إلى بعض الأوصاف الحسية للمتحف، اذكر بعضها.</li><li>(هـ) وضِّحْ بعضَ المشاعر التي يثيرها المتحف في نفوس زائريه.</li><li>(و) ما الانطباع النهائي الذي تركه الكاتب عن المتحف في الخاتمة؟</li></ul><div class='mh'>الإجابة</div><ul class='dash'><li>(أ) اختار الكاتب عنوان «كنز مصر الحضاري الجديد»، وما يميزه أنه عنوان جذاب؛ حيث يشير إلى قيمة المتحف الحضارية.</li><li>(ب) أن المتحف يعدُّ منارة ثقافية تضيء طريق المستقبل بنور الماضي المجيد.</li><li>(ج) ١- مساحته أكثر من ٣٠٠ ألف متر مربع. ٢- أنه تحفة معمارية حديثة. ٣- الحدائق الشاسعة حول المتحف والتي تمتلئ بالنباتات والنخيل.</li><li>(د) رائحة التاريخ المهيبة – همسات الزوار – أصوات الأقدام – الأضواء – الألوان الساحرة.</li><li>(هـ) الهيبة والجلال والدهشة والإعجاب.</li><li>(و) أنَّ المتحف المصري الكبير رمزٌ لعظمة الحضارة المصرية.</li></ul>","tb1_tatbiq":"<div class='mh'>نموذج تطبيقي</div><p class='tx'>- بالاستعانة بالعناصر التالية اكتب مقال وصف مكان زُرتُه وأعجبك وترك فيك أثرًا لا يُنسى:</p><ul class='dash'><li>العنوان</li><li>المقدمة</li><li>الموضوع: الأوصاف الخارجية – الأوصاف الداخلية – الأوصاف الحسية – الجو العام للمكان – وصف مظاهر الحركة والنشاط في المكان</li><li>الخاتمة</li></ul><p class='tx'>[تنبيه: باقي صفحة النموذج التطبيقي في النسخة الممسوحة عبارة عن سطور منقطة فارغة مخصصة لكتابة الطالب.]</p>","tb1_tr1":"<div class='mh'>تدريب ١ — المستوى الأول — السؤال ١</div><p class='tx'>اقرأ مقال وصف دير سانت كاترين، ثمَّ اكتب بأسلوبكَ وصفًا خارجيًّا له مستعينًا بما يَلي: (بداخله برج الأجراس - يحيط به الجبال الشاهقة - البساتين الصغيرة من حوله - صخور الجرانيت المنتشرة)</p><p class='tx'><b>دير سانت كاترين... قلب التاريخ وروح الصحراء</b></p><p class='tx'>في أعماق شبه جزيرة سيناء، يقع دير سانت كاترين على سفوح جبل سيناء، ويحمل هذا المكان قدسيةً وتاريخًا عريقًا يمتد لأكثر من ألف وخمسمائة عام.</p><p class='tx'>وتضم جدران الدير كنيسة التجلي بقبتها البيزنطية الرائعة، وأيقوناتها النادرة التي تزين الجدران الحجرية. وتحتوي مكتبة الدير على آلاف المخطوطات النادرة باللغات اليونانية والعربية والسريانية، محفوظة في خزائن خشبية عتيقة.</p><p class='tx'>وتنتشر في أرجاء الدير رائحة البخور المختلطة بعبق التاريخ والأحجار العتيقة، ويسود المكان صمت تكسره أصوات أجراس الكنيسة التي تدق في أوقات الصلاة، وتتميز جدران الدير الحجرية بلونها الذهبي الباهت. ويسود الدير جو من السكينة، يشعر الزائر فيه بالهدوء والطمأنينة. وهكذا يبقى دير سانت كاترين شاهدًا على عراقة التاريخ وروحانية المكان. إنه ليس مجرد بناء حجري، بل قصة خالدة ترويها الجبال والصخور لكل من يبحث عن الجمال والسلام في أعماق الصحراء.</p>","tb1_tr2":"<div class='mh'>تدريب ١ — المستوى الأول — السؤال ٢</div><p class='tx'>اقرأ مقال وصف مكتبة الإسكندرية، ثمَّ اكتب بأسلوبكَ وصفًا داخليًّا لها مستعينًا بما يَلي: (بهو واسع - سقف عالٍ مُغطًّى بقبَّة زجاجية - ٨ قاعاتٍ للقراءة - طاولات خشبية - كراسيٌّ - أجهزة حاسوب حديثة - قاعة الكتب النادرة - قاعة المؤتمرات - مناطق استراحة للزائرين).</p><p class='tx'><b>منارة المعرفة المتجددة</b></p><p class='tx'>على شاطئ البحر الأبيض المتوسط، وفي مدينة الإسكندرية، تقع مكتبة الإسكندرية، والتي تُعتبر واحدة من أهم مراكز العلم والثقافة في مصر والعالم، وتعد مكتبة الإسكندرية نافذة ثقافية للالتقاء الفكري، وملاذًا لكل قارئ يبحث عن نور العلم والمعرفة.</p><p class='tx'>تقع المكتبة في منطقة الشاطبي بالإسكندرية، وتُطِلُّ على البحر الأبيض المتوسط بواجهة زجاجية ساحرة، ويتميز مبنى المكتبة بتصميمه الدائري الفريد الذي يشبه قرص الشمس المائل، ويعلوه سقف مائل من الألومنيوم والزجاج مغطى بالنقوش والرموز من مختلف الحضارات. وتحيط بالمكتبة حدائق غنَّاء تضم مجسمات أثرية ونوافير مائية تضفي على المكان جمالًا خاصًّا.</p><p class='tx'>وتنبعث من قاعات المكتبة رائحة الكتب الجديدة المختلطة بعبير البحر القادم من النوافذ المفتوحة، ويسود المكان هدوء تخترقه همسات القراء وأصوات تقليب الصفحات، وتضيء المكتبة إضاءة طبيعية تتدفق من السقف الزجاجي، وتشعِرُنَا الألوان الهادئة للمكان بالراحة والتركيز.</p><p class='tx'>وتسود المكتبة أجواء علمية وثقافية تشجِّعُ على القراءة والتعلُّم والبحث؛ حيث يشعر الزائر بالإلهام والشغف الدائم للمعرفة.</p><p class='tx'>تشهد قاعات المكتبة حركة دائمة من الطلاب والباحثين، وتُقام فيها محاضرات ومؤتمرات علمية، ومعارض فنية وثقافية بانتظام.</p><p class='tx'>إنَّ مكتبة الإسكندرية هي أكثر من مجرد مكتبة، إنها مركز إشعاع ثقافي يضيء طريق المستقبل بنور العلم والمعرفة.</p>","tb1_tr3":"<div class='mh'>تدريب ١ — المستوى الأول — السؤال ٣</div><p class='tx'>اقرأ مقال وصف واحة سيوة، ثمَّ اكتب بأسلوبكَ فقرةً عن الأوصاف الحسِّيَّةِ لها مستعينًا بما يَلي: (رائحة النخيل المختلطة بالتمر الناضج - رائحة المياه الكبريتية الساخنة من العيون الطبيعية - أصوات حفيف أوراق النخيل - خرير المياه الهادئ - أصوات العصافير - أصوات الضفادع - أشجار النخيل الخضراء - الرمال الذهبية - المياه الزرقاء - الرمال الناعمة).</p><p class='tx'><b>لؤلؤة الصحراء الساحرة</b></p><p class='tx'>في أعماق الصحراء الغربية، تقعُ واحة سيوة كجوهرة خضراء وسط بحر من الرمال الذهبية. هذه الواحة الساحرة التي تحمل في طياتها جمالًا طبيعيًّا فريدًا يأسر القلوب ويسحر العقول.</p><p class='tx'>تمتد واحة سيوة على مساحة واسعة، ويحيط بها كثبان رملية ذهبية، وتنتشر في الواحة بساتين النخيل التي تشكل مظلة طبيعية خضراء، وتتوزع بينها البحيرات المالحة ذات المياه الزرقاء الصافية. وتقف قلعة شالي القديمة على تلة مرتفعة كحارس صامت يُطِلُّ على الواحة.</p><p class='tx'>وتتكون الواحة من عدة قرى صغيرة، بيوتها مبنية من الطوب اللِّبن والملح الصخري، وتنتشر في الواحة عيون المياه الطبيعية الساخنة والباردة، وتتميز شوارعها الضيقة بطابعها الشعبي الأصيل.</p><p class='tx'>تتميز واحة سيوة بجو من الهدوء والسكينة؛ حيث يشعر الزائر بالسلام الداخلي والانسجام مع الطبيعة. إنها مكان مثالي للهروب من ضغوط الحياة والاستمتاع بجمال الطبيعة.</p><p class='tx'>وفي واحة سيوة يمارس الأهالي مهنة الزراعة، ويستقبلون السياح بحفاوةٍ بالغةٍ، وتقام في الواحة رحلات السفاري في الصحراء المحيطة.</p><p class='tx'>وهكذا تعد واحة سيوة قطعة من الجنة على الأرض؛ حيث إنَّهَا مكانٌ يجمع بين سحر الصحراء وجمال الطبيعة، كما أنَّهَا ملاذٌ للباحثين عن الهدوء والجمال الطبيعي.</p>","tb1_tr4":"<div class='mh'>تدريب ١ — المستوى الأول — السؤال ٤</div><p class='tx'>اقرأ مقال وصف قلعة صلاح الدين الأيوبي، ثُمَّ اكتب بأسلوبكَ خاتمةً مناسبةً له، ووضِّحْ فيها الانطباع العام عن القلعة ومشاعرك تجاهها.</p><p class='tx'><b>حصن التاريخ العريق</b></p><p class='tx'>تعد قلعة صلاح الدين الأيوبي إحدى أعرق القلاع الحربية التي شُيِّدَتْ في العصر الأيوبي، وقد أتاح لها موقعها الاستراتيجي على تلٍّ صخريٍّ مُجاوِرٍ لجبل المُقَطَّم إطلالةً رائعةً على كل معالم القاهرة التاريخية.</p><p class='tx'>تقف القلعة شامخة فوق جبل المقطم، وقد بدأ بناؤها عام ١١٧٦م في عهد صلاح الدين الأيوبي، ولم يكتمل البناء حتى عام ١١٨٢م. وتحيط بها أسوار عالية من الحجر الجيري الصلب، تتخللها أبراج دفاعية ضخمة وبوَّابات محصنة، وتضم القلعة عدة مبانٍ ومساجد وقصور.</p><p class='tx'>وتحتوي القلعة على مسجد محمد على، بالإضافة إلى عدة متاحف تضم مجموعاتٍ نادرةً من الأسلحة القديمة والمخطوطات التاريخية. وتتميز الممرات الداخلية الموجودة في القلعة بأقواسها الحجرية والنقوش الإسلامية الدقيقة المحفورة على الجدران.</p><p class='tx'>وتنساب الألوان الرملية لحجارة القلعة بانسجام مع زرقة السماء الصافية، وتنعكس أشعة الشمس على القباب والمآذن؛ فترسم لوحة بصرية تخطب الأنظار بجمالها، ويخيم على المكان هدوءٌ لا يقطعه سوى خرير النوافير المنتشرة وصوت تلاوة القرآن الكريم الذي ينبعث بخشوع من جنبات المسجد؛ ليضفي على الأجواء هيبة وروحانية لا تُنسى.</p><p class='tx'>ويسيطر على القلعة جوٌّ من الجلال والهيبة التاريخية؛ حيث يشعر الزائر وكأنه يعيش في أحد أروقة التاريخ الإسلامي العريق. إنها مكانٌ يبعث في النفس مشاعر الفخر بالتراث العربي والإسلامي.</p><p class='tx'>وينتشر في القلعة الزائرون الذين يتجولون بين المعالم التاريخية المختلفة، ويلتقطون الصور التذكارية، والأطفال الذين يركضون في الساحات الواسعة، وكبار السن الذين يجلسون على المقاعد الحجرية.</p>","tb1_tr5":"<div class='mh'>تدريب ١ — المستوى الثاني — السؤال ٥</div><p class='tx'>اختر أحدَ الأماكن الآتية: (الحديقة العامة - شاطئ البحر الذي زرته - مكتبة المدرسة - حديقة الألعاب «الملاهي» - ناديك الرياضي - مطعم العائلة المُحَبَّب - محطة القطار في مدينتك - معرض الكتاب السنوي)، ثُمَّ اكتب في دفترك مقالًا لوصفِهِ، مع مراعاة عناصر المقال (مقدمة - موضوع - خاتمة)، والتركيز على وصف المكان وصفًا معبرًا ودقيقًا، وإظهار الجو العام فيه، ومع الالتزام بالمفردات والتعبيرات المناسبة، والتسلسل المنطقي للأفكار، وسلامة الإملاء والخط، على أن يتراوح عدد كلمات المقال بين (١٣٠ - ١٧٠) كلمة.</p>","tb2_def":"<div class='mh'>الخطبة الإقناعية</div><p class='tx'>هي نص أدبيٌّ يهدف إلى إقناع المستمعين بفكرة معينة، أو دعوتهم لاتخاذ موقف محدد من قضية ما، وذلك من خلال استخدام الأدلة والمعلومات الصحيحة والأساليب المؤثرة.</p>","tb2_steps":"<div class='mh'>خطواتُ كتابةِ خطبةٍ إقناعية</div><ul class='dash'><li><b>أولًا:</b> اختيار موضوع مناسب يهم الجمهور المستهدف. <b>ثانيًا:</b> تحديد الهدف من الخطبة والرسالة المراد إيصالها.</li><li><b>ثالثًا:</b> جمع الأدلة والبراهين المؤيدة للفكرة الأساسية. <b>رابعًا:</b> كتابة المقدمة الجاذبة للانتباه.</li><li><b>خامسًا:</b> كتابة الفِكر الرئيسة مع الأدلة والبراهين. <b>سادسًا:</b> كتابة خاتمة مناسبة.</li><li><b>سابعًا:</b> مراجعة النص وتنقيحه.</li></ul>","tb2_elems":"<div class='mh'>عناصر كتابة الخطبة الإقناعية</div><table class='plain'><tr><th>العنصر</th><th>بيانه</th></tr><tr><td><b>١- العنوان</b></td><td>لا بد أن يكون عنوانًا معبرًا، جذابًا، مثل: «نحو مجتمع متقدم»، أو: «أهمية العلم في حياتنا».</td></tr><tr><td><b>٢- المقدمة</b></td><td>وتشمل: ١- التحية: «السلام عليكم»، أو «أيها الأصدقاء الأعزاء». ٢- تعريفًا بالموضوع وأهميته بشكل موجز.</td></tr><tr><td><b>٣- الموضوع</b></td><td>ويشمل: ١- الفكرة الأولى + الدليل عليها. ٢- الفكرة الثانية + الدليل عليها. ٣- الفكرة الثالثة + الدليل عليها. «لا يشترط أن يكون عدد الفِكر ثلاثًا، ربما يكون أكثر من ثلاث وربما أقل منها».</td></tr><tr><td><b>٤- الخاتمة</b></td><td>وتشمل: ١- تلخيص الفِكر الأساسية في جملة واحدة. ٢- دعوة المستمعين للعمل أو التطبيق. ٣- جملة ختامية مؤثرة.</td></tr></table>","tb2_note":"<div class='mh'>لا تنس</div><ul class='dash'><li>١- استخدام أساليب الإقناع: أسلوب الاستفهام، النداء، التشبيه، الأدلة والبراهين لجعل الكلام مؤثرًا.</li><li>٢- الأدلة والبراهين تشمل: آيات قرآنية – أحاديث نبوية – أبياتًا شعرية – أقوالًا مأثورة – حقائق علمية وإحصائيات – أمثلة من الواقع – تجارب شخصية أو تاريخية.</li></ul>","tb2_model":"<div class='mh'>نموذج تعريفي (مجاب عنه): خطبة إقناعية</div><p class='tx'><b>العنوان:</b> القراءة سلاح المستقبل</p><p class='tx'><b>المقدمة:</b> أصدقائي الأعزَّاء، هل تعلمون أن الشباب في الدول المتقدمة يقرءون بمعدل ٥٠ كتابًا سنويًّا، بينما نحن لا نتجاوز كتابين في العام الواحد؟ هذا الرقم المؤلم يدق ناقوس الخطر حول مستقبلنا الثقافي والحضاري.</p><p class='tx'><b>الموضوع — الفكرة الأولى مع الأدلة:</b> إن القراءة، أيها الأصدقاء، ليست مجرد هواية أو وسيلة لقضاء الوقت، بل هي غذاء العقل وسلاح المستقبل. فالقراءة تنمي قدراتنا الفكرية، وتوسِّع مداركنا، وتجعلنا أكثر قدرة على فهم العالم من حولنا.</p><p class='tx'><b>الفكرة الثانية مع الأدلة:</b> وانظروا إلى أعظم الشخصيات في التاريخ، ستجدون أنهم جميعًا كانوا قرَّاءً نهمين، فالجاحظ مثلًا كان لا يقع بيده كتاب إلا قرأه من أوله لآخره، وابن خلدون قرأ معظم الكتب المتوافرة في عصره في التاريخ والفقه والفلسفة والأدب.</p><p class='tx'><b>الفكرة الثالثة مع الأدلة:</b> والقراءة تساعدنا على تطوير مهاراتنا اللغوية والتعبيرية، فالذي يقرأ كثيرًا يكتب بشكل أفضل، ويتحدث بطلاقة أكبر، ويصبح أكثر ثقة في التعامل مع الآخرين.</p><p class='tx'><b>الخاتمة:</b> لذلك أدعوكم جميعًا، أيها الأصدقاء الأعزاء، إلى أن تجعلوا القراءة عادة يومية. ابدءوا بكتاب واحد شهريًّا، ثم كتابين وثلاثة، وهكذا تدريجيًّا. استثمروا في عقولكم، فهي أغلى ما تملكون.</p>","tb2_model_q":"<div class='mh'>بعد قراءة النموذج التعريفي السابق، أجب عمَّا يلي</div><ul class='dash'><li>(أ) ما العنوان الذي اختاره الكاتب للخطبة؟ وما رأيك فيه؟</li><li>(ب) كيف تمكَّنَ الخطيب من جذب انتباه المستمعين في بداية الخُطبة؟</li><li>(ج) اذكر الفِكرَ الرئيسة التي اعتمدت عليها الخطبة لترشدنا إلى أهمية القراءة.</li><li>(د) وردتْ بالخطبة بعضُ الدلائل والبراهين التي تدلُّ على أهمية القراءة، اذكر بعضَها.</li><li>(هـ) ما الدعوة التي وجهها الخطيب في النهاية؟</li></ul><div class='mh'>الإجابة</div><ul class='dash'><li>(أ) «القراءة سلاح المستقبل»؛ يدلُّ على شدة تأثير القراءة على حياتنا في المستقبل.</li><li>(ب) من خلال الإحصائية التي ذكرها حول معدل القراءة في الدول المتقدمة ومعدلها في بلادنا.</li><li>(ج) القراءة غذاء العقل وتنمي القدرات الفكرية – أعظم الشخصيات كانوا قراءً نهمين – القراءة تطور المهارات اللغوية والتعبيرية.</li><li>(د) القراءة تنمي قدراتنا الفكرية، وتوسِّع مداركنا، وتجعلنا أكثر قدرة على فهم العالم من حولنا.</li><li>(هـ) جَعْل القراءة عادة يومية والبدء بكتاب واحد شهريًّا.</li></ul>","tb2_tatbiq":"<div class='mh'>نموذج تطبيقي</div><p class='tx'>- بالاستعانة بالعناصر التالية اكتب خطبة إقناعية لعرضها على زملائك عن السَّفَر وفوائده في حياتنا:</p><ul class='dash'><li>العنوان</li><li>المقدمة</li><li>الموضوع: الفكرة الأولى مع الأدلة – الفكرة الثانية مع الأدلة – الفكرة الثالثة مع الأدلة</li><li>الخاتمة</li></ul><p class='tx'>[تنبيه: باقي صفحة النموذج التطبيقي في النسخة الممسوحة عبارة عن سطور منقطة فارغة مخصصة لكتابة الطالب.]</p>","tb2_tr1":"<div class='mh'>تدريب ٢ — المستوى الأول — السؤال ١</div><p class='tx'>اقرأ الخطبة الإقناعية التالية، ثُمَّ اكتب مقدمةً وخاتمةً مناسبتين لها:</p><p class='tx'><b>التنمر: خطر يهدد أطفالنا ومدارسنا</b></p><p class='tx'>يسبب التنمر أضرارًا نفسية خطيرة قد تستمر مدى الحياة؛ حيث إنَّ من يتعرض للتنمر يفقد ثقته بنفسه، ويُصاب بالاكتئاب والقلق، ويصبح خائفًا من المدرسة. وبالإضافة إلى ذلك، يؤثر التنمر على الأداء الأكاديمي للطالب المتنمَّر عليه؛ إذ كيف يمكن لطالب أن يركز في الدرس وهو يشعر بالخوف والقلق؟! وقد أشارت الإحصائيات إلى أن درجات ضحايا التنمر تنخفض بمعدل ٢٠١٥-٢٠٪.</p><p class='tx'>ولا ننسى أن التنمر يخلق بيئة مدرسية سيئة تؤثر على الجميع، حتى أولئك الطلاب الذين لا يتعرضون للتنمر يشعرون بعدم الأمان والتوتر؛ مما يجعل المدرسة مكانًا مكروهًا بدلًا من أن تكون بيتهم الثاني.</p><p class='tx'>[تنبيه: عبارة «بمعدل ٢٠١٥-٢٠٪» واردة في النسخة الممسوحة بهذا الشكل غير الواضح، والأرجح أنها «بمعدل ١٥-٢٠٪».]</p>","tb2_tr2":"<div class='mh'>تدريب ٢ — المستوى الأول — السؤال ٢</div><p class='tx'>اقرأ الخطبة الإقناعية التالية، ثُمَّ اكتب الفكرة الأولى لها مع ذكر الأدلة والبراهين المتعلقة بها:</p><p class='tx'><b>فن تنظيم الوقت</b></p><p class='tx'>أبنائي الأحبَّاء، ماذا لو أخبرتكم أن الطلاب الناجحين لا يدرسون أكثر من الآخرين، بل ينظمون وقتهم بشكل أفضل، وأن ٨٠٪ من المتفوقين يقضون وقتًا أقل في المذاكرة، لكنهم يحققون نتائج أفضل؟ تنظيم الوقت يا أبنائي مفتاح سحري يفتح لكم أبواب النجاح والتفوق. وتنظيم الوقت أمرٌ مهمٌّ؛ لأن معظمكم يشكو من ضيق الوقت وعدم القدرة على إنجاز المطلوب، رغم أن لديكم نفس الساعات التي يملكها المتفوقون.</p><p class='tx'>والتنظيم الجيد للوقت يخلق وقتًا إضافيًّا للأنشطة الممتعة، فعندما تنظمون وقت الدراسة وتركزون فيه؛ ستنهون المطلوب بسرعة أكبر؛ مما يتيح لكم وقتًا للعب والخروج مع الأصدقاء.</p><p class='tx'>وتنظيم الوقت مهارة حياتية ستفيدكم في المستقبل، في الجامعة والعمل، ستواجهون مهامَّ متعددة ومواعيد نهائية صارمة، والشخص المنظم يتفوق على الذكي غير المنظم، وتبحث الشركات اليوم عن موظفين ينجزون المهام في الوقت المحدد أكثر من بحثها عن العباقرة.</p><p class='tx'>وختامًا يقللُّ تنظيم الوقت من التوتر، ويخلقُ وقتًا للمتعة، ويبني مهارات المستقبل؛ ولذا بدءًا من اليوم ضعوا جدولًا أسبوعيًّا واضحًا، وخصصوا أوقاتًا محددة للدراسة والراحة، والتزموا به لأسبوعين، وستلاحظون الفرق، وتذكروا دائمًا أنَّ الوقت كالسيف، إن لم تقطعه قطعك.</p>","tb2_tr3":"<div class='mh'>تدريب ٢ — المستوى الأول — السؤال ٣</div><p class='tx'>اقرأ الخطبة الإقناعية التالية، ثُمَّ اكتب الفكرة الثانية لها مع ذكر الأدلة والبراهين المتعلقة بها:</p><p class='tx'><b>مهاراتك مستقبلك</b></p><p class='tx'>أيها الطلاب المبدعون، هل تعلمون أن الشخص الذي يتقن مهارتين مختلفتين يحصل على راتب أعلى بنسبة ٤٠٪ من الذي يتقن مهارة واحدة فقط، وأن ٩٠٪ من الوظائف المستقبلية ستتطلب مهارات متعددة؟ تعلُّم المهارات الجديدة ليس مجرد هواية، بل هو استثمار في مستقبلكم ونجاحكم.</p><p class='tx'>وينَمِّي تعلم المهارات الجديدة الذكاء ويحسن الأداء الدراسي؛ حيث إنكم عندما تتعلمون مهارة جديدة مثل الرسم أو البرمجة تتكون روابط جديدة في الدماغ تزيد من سرعة التفكير والتذكر، وقد أثبتت دراسة علمية أن الطلاب الذين يتعلمون مهارات إضافية يحصلون على درجات أعلى بنسبة ٢٠٪.</p><p class='tx'>والأهم من ذلك، يزيد تعلم المهارات من الثقة بالنفس، ويجعلكم مميزين بين أقرانكم. تخيلوا كم ستشعرون بالفخر عندما تتعلَّمُونَ لغةً جديدةً، أو ترسمون لوحة رائعة، أو تصممون موقعًا إلكترونيًّا. هذا التميز يجعل الآخرين ينظرون إليكم بإعجاب واحترام.</p><p class='tx'>وفي الختام ينمي تعلم المهارات الجديدة الذكاء، ويفتح آفاقًا مهنية، ويزيد الثقة بالنفس؛ ولذا عليكم – يا أبنائي – أن تختاروا من الآن مهارة واحدة تحبونها، وأن تستمروا في تعلمها، وخصصوا لها ساعة يوميًّا، واستفيدوا من الدورات المجانية المتعلقة بها، واستثمروا في أنفسكم اليوم لتحصدوا ثمار النجاح غدًا.</p>","tb2_tr4":"<div class='mh'>تدريب ٢ — المستوى الأول — السؤال ٤</div><p class='tx'>اقرأ الخطبة الإقناعية التالية، ثُمَّ اكتب الفكرة الثالثة لها مع ذكر الأدلة والبراهين المتعلقة بها:</p><p class='tx'><b>اختر صديقك بعناية</b></p><p class='tx'>أبناءنا المتميزينَ، من منكم لديه صديق يثق به تمامًا؟ ومن منكم شعر بالحزن عندما انتقل صديقه إلى مدرسة أخرى؟ هذا دليل على قوة الصداقة الحقيقية في حياتنا. إن اختيار الأصدقاء الجيدين قرار يؤثر على شخصيتنا ومستقبلنا وسعادتنا؛ فالإنسان بطبعه اجتماعي، والأصدقاء هم مرآتنا التي نرى فيها أنفسنا، ورفاق دربنا في رحلة الحياة.</p><p class='tx'>والصديق الجيد يؤثر إيجابيًّا على سلوكنا وأخلاقنا، وقد أكدتِ الدراسات أن الشباب يتأثرون بأصدقائهم أكثر من أي مؤثر آخر، وقد قال الرسول ﷺ: «المرء على دين خليله؛ فلينظر أحدكم من يُخَالِل».</p><p class='tx'>والأصدقاء الحقيقيون يساعدوننا في أوقات الضعف والحاجة؛ فهم الذين يقفون بجانبنا عندما نحتاج إليهم، ويشجعوننا على تحقيق أهدافنا، ويساعدوننا على تجاوز الصعوبات والتحديات.</p><p class='tx'>إذن، الصديق الجيد يؤثر إيجابيًّا على سلوكنا، ويساعدنا في أوقات الشدَّة، ويزيد من سعادتنا؛ ولذا عليكم أن تختاروا أصدقاءكم بعناية، وأن تبحثوا عن الصادقين والأمناء والمتفوقين، وكونوا أنتم أيضًا أصدقاء جيدين للآخرين.</p>","tb2_tr5":"<div class='mh'>تدريب ٢ — المستوى الثاني — السؤال ٥</div><p class='tx'>اختر أحد الموضوعات الآتية: (الأمانة - الصدق - العدل - تعلم اللغات - التدخين - العمل التطوعي - الطعام الصحي - حسن الخلق - احترام حقوق الجيران - التلوث - تقبُّل الاختلاف - ترشيد استهلاك الماء)، ثُمَّ اكتب خطبة إقناعية حوله، مع مراعاة عناصر الخطبة الإقناعية (عنوان - مقدمة - موضوع – خاتمة)، واختيار المفردات والتعبيرات الدقيقة والمناسبة، والتسلسل المنطقي للخطبة الإقناعية، مع إملاء وخطٌّ سليمين، بعدد كلمات يتراوح بين (١٣٠ – ١٧٠) كلمة.</p>","tbx_q1":"<div class='mh'>تدريبات التعبير الكتابي الشاملة — السؤال ١</div><p class='tx'>قم بتصنيف الجمل الآتية وفق عناصر مقال وصف المكان:</p><p class='tx'>تبعث أجواء المحمية في النفس الراحة والطمأنينة – تتنوع الأسماك بألوانها الزاهية وأشكالها المدهشة – تحيط بالمحمية مياه البحر الأحمر الزرقاء الصافية من ثلاث جهات – يمارس الزوار رياضة الغوص لاستكشاف عالم الشعاب المرجانية – تمتد الشواطئ الرملية البيضاء على طول السواحل المتعرجة – تعد محمية رأس محمد إحدى أهم المحميات الطبيعية في العالم – يمتزج صوت الأمواج الهادئة مع أصوات الطيور المهاجرة – يحيط بالمحمية جبال سيناء الشاهقة ذات الألوان الذهبية والحمراء – زيارة رأس محمد تجربة لا تُنسى تبقى محفورة في الذاكرة – محمية رأس محمد.. لؤلؤة سيناء الساحرة – تزدهر الشعاب المرجانية الملونة في أعماق المياه الدافئة – تنتشر رائحة الملح المنعشة مع عبير الأعشاب البحرية – تتلألأ المياه تحت أشعة الشمس – تنمو أشجار المنجروف الخضراء على ضفاف البحيرات المالحة – يستمتع السياح برحلات القوارب الزجاجية لمشاهدة الأسماك – محمية رأس محمد كنز طبيعي يجب المحافظة عليه للأجيال القادمة.</p><p class='tx'>(أ) العنوان: ......... (ب) المقدمة: ......... (ج) الأوصاف الخارجية: ......... (د) الأوصاف الداخلية: ......... (هـ) الأوصاف الحسية: ......... (و) وصف الجو العام: ......... (ز) وصف مظاهر النشاط والحركة: ......... (ح) الخاتمة: .........</p>","tbx_a1":"<div class='mh'>إجابة نموذجية للسؤال ١ (التصنيف)</div><table class='plain'><tr><th>العنصر</th><th>الجمل المناسبة</th></tr><tr><td><b>(أ) العنوان</b></td><td>محمية رأس محمد.. لؤلؤة سيناء الساحرة.</td></tr><tr><td><b>(ب) المقدمة</b></td><td>تعد محمية رأس محمد إحدى أهم المحميات الطبيعية في العالم.</td></tr><tr><td><b>(ج) الأوصاف الخارجية</b></td><td>تحيط بالمحمية مياه البحر الأحمر الزرقاء الصافية من ثلاث جهات. – تمتد الشواطئ الرملية البيضاء على طول السواحل المتعرجة. – يحيط بالمحمية جبال سيناء الشاهقة ذات الألوان الذهبية والحمراء.</td></tr><tr><td><b>(د) الأوصاف الداخلية</b></td><td>تتنوع الأسماك بألوانها الزاهية وأشكالها المدهشة. – تزدهر الشعاب المرجانية الملونة في أعماق المياه الدافئة. – تنمو أشجار المنجروف الخضراء على ضفاف البحيرات المالحة.</td></tr><tr><td><b>(هـ) الأوصاف الحسية</b></td><td>يمتزج صوت الأمواج الهادئة مع أصوات الطيور المهاجرة. – تنتشر رائحة الملح المنعشة مع عبير الأعشاب البحرية. – تتلألأ المياه تحت أشعة الشمس.</td></tr><tr><td><b>(و) وصف الجو العام</b></td><td>تبعث أجواء المحمية في النفس الراحة والطمأنينة.</td></tr><tr><td><b>(ز) وصف مظاهر النشاط والحركة</b></td><td>يمارس الزوار رياضة الغوص لاستكشاف عالم الشعاب المرجانية. – يستمتع السياح برحلات القوارب الزجاجية لمشاهدة الأسماك.</td></tr><tr><td><b>(ح) الخاتمة</b></td><td>زيارة رأس محمد تجربة لا تُنسى تبقى محفورة في الذاكرة. – محمية رأس محمد كنز طبيعي يجب المحافظة عليه للأجيال القادمة.</td></tr></table>","tbx_q2":"<div class='mh'>السؤال ٢</div><p class='tx'>بعد أن قمتَ بتصنيف العناصر السابقة، اكتب مقالًا لوصف محمية رأس محمد بأسلوبك:</p>","tbx_q3":"<div class='mh'>السؤال ٣</div><p class='tx'>بالاستعانة بالجمل الآتية، اكتب خطبة إقناعية حول «ترشيد استهلاك المياه»:</p><p class='tx'>«قطرة الماء... قطرة الحياة – أصدقائي الأعزاء، هل تعلمون أن مليار إنسان في العالم لا يجدون ماءً نظيفًا للشرب؟ – ترشيد استهلاك الماء يحافظ على هذه النعمة للأجيال القادمة – ترشيد الاستهلاك يوفر المال ويقلل الفواتير – قال تعالى: ﴿وَجَعَلْنَا مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ﴾ – أدعوكم لإقفال الصنبور جيدًا وإصلاح أي تسريب فورًا – تذكروا أن كل قطرة ماء نوفرها اليوم هي هدية لأطفال المستقبل».</p>","tbx_q4":"<div class='mh'>السؤال ٤</div><p class='tx'>أكمل هذه الخطبة الإقناعية التي تدور حول «حماية البيئة»:</p><p class='tx'>أيها الطُّلاب المتميزونَ، ................. يهدد التلوث البيئي حياتنا ومستقبل أجيالنا القادمة، ونحن نشهد اليوم تدهورًا خطيرًا في جودة الهواء والماء والتربة، .................، وقد قال الله –تعالى–: ﴿وَلَا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلَاحِهَا﴾، وهذا يدل على أن حماية البيئة واجب ديني قبل أن يكون واجبًا إنسانيًا. وكل فرد منا مسئول عن حماية البيئة، والتغيير يبدأ من الخطوات الصغيرة، ففي اليابان مثلًا يقوم كل مواطن بفصل النفايات في منزله إلى عدة أصناف ووضعها في أكياس ملونة مختلفة. هذا السلوك اليومي البسيط زاد من معدل إعادة تدوير النفايات، وقلَّلَ النفايات التي يتم دفنها والتخلص منها، وجعل اليابان من أنظف دول العالم بيئيًّا. .................، فلنبدأ من اليوم بخطوات بسيطة، ................. ولنتذكر دائمًا أن البيئة من حولنا أمانة في أعناقنا».</p>","tbx_q5":"<div class='mh'>السؤال ٥</div><p class='tx'>اختر أحد الموضوعات الآتية: (الثقة بالنفس - الصبر والمثابرة - التواضع وعدم الغرور - التحكم في الغضب - التعامل مع ضغوط الامتحانات - التغذية السليمة - الهواتف الذكية وتأثيرها على الطلاب - مخاطر الإنترنت وكيفية تجنبها - أهمية إعادة التدوير - الفقر وسبل مكافحته)، ثُمَّ اكتب خطبة إقناعية حوله، مع مراعاة عناصر الخطبة الإقناعية (عنوان - مقدمة - موضوع – خاتمة)، واختيار المفردات والتعبيرات الدقيقة والمناسبة، والتسلسل المنطقي للخطبة الإقناعية، مع إملاء وخطٌّ سليمين بعدد كلمات يتراوح بين (١٣٠ – ١٧٠) كلمة.</p>"});
Object.assign(S,{"tb1_def":"وصف المكان يعني إنك تنقل صورة المكان للي قدامك كأنه شايفه بعينه. مش بس تقوله المكان فين، لأ، لازم يتخيله ويحس بجوّه ويشوف اللي بيميزه. يعني كأنك بتاخد إيد القارئ وبتلف بيه جوه المكان.","tb1_steps":"قبل ما تمسك القلم امشي على الخطوات دي بالترتيب: أول حاجة اختار مكان تعرفه كويس وتقدر توصفه. تاني حاجة اسأل نفسك: أنا عايز أوصل إيه للقارئ؟ إيه الانطباع اللي عايز أسيبه؟ تالت حاجة جمّع كل التفاصيل والأوصاف اللي تعرفها عن المكان ورتبها ترتيب منطقي. ورابع حاجة بعد ما تخلص راجع كلامك واتأكد إن الأفكار ماشية ورا بعض وكلامك واضح.","tb1_elems":"مقال وصف المكان مبني على أربع حاجات: العنوان لازم يكون جذاب ويدل على المكان زي «حديقة الأحلام». المقدمة فيها تعريف سريع بالمكان وليه اخترته. الموضوع ده قلب المقال وبيشمل خمس حاجات: الأوصاف الخارجية زي الموقع والمساحة، والأوصاف الداخلية زي التفاصيل والتصميم، والأوصاف الجسية يعني اللي بتلمسه بحواسك: الألوان والأصوات والروائح، وبعدين الجو العام للمكان: هادئ ولا صاخب؟ بيفرحك ولا بيهديك؟، وأخيرًا مظاهر الحركة والنشاط فيه. والخاتمة بتلخص انطباعك العام ومشاعرك وتسيب رسالة في نفس القارئ.","tb1_model":"بص على النموذج ده كويس عشان هو اللي هتحتذي بيه. لاحظ الكاتب مشى على العناصر بالظبط: بدأ بعنوان جذاب «كنز مصر الحضاري الجديد»، وبعدين مقدمة فيها تعريف بالمكان وأهميته، وبعدين وصف برّه: المساحة والشكل المعماري والحدائق، وبعدين وصف جوّه: البهو والأعمدة وصالات العرض والإضاءة، وبعدين وصف بحواسه: رائحة التاريخ وهمسات الزوار والألوان الساحرة، وبعدين الجو العام: الهيبة والجلال والدهشة، وبعدين الحركة والنشاط: الزائرون بيتفرجوا والمرشدون بيشرحوا والسياح بيصوروا، وقفل بخاتمة فيها الانطباع العام والفخر بالحضارة. امشِ على نفس الترتيب في أي مقال وصف مكان هتكتبه.","tb1_model_q":"الأسئلة دي بتتأكد إنك فاهم النموذج مش حافظه. لما يسألك عن العنوان ومميزه، افتكر إن العنوان الجيد بيكون جذاب ومعبر. ولما يسألك عن عناصر الوصف الخارجي، دور في فقرة الأوصاف الخارجية: المساحة والشكل والحدائق. والأوصاف الحسية هي كل حاجة ليها علاقة بالحواس: شم وسمع وبصر. والمشاعر هتلاقيها في فقرة الجو العام. والانطباع النهائي في الخاتمة.","tb1_tatbiq":"دلوقتي دورك تطبق اللي فهمته. اختار مكان زرته وأعجبك فعلًا، واكتب عنه مقال وصف كامل بالعناصر اللي اتفقنا عليها: عنوان، مقدمة، موضوع فيه الأوصاف الخارجية والداخلية والحسية والجو العام ومظاهر الحركة والنشاط، وخاتمة. متستعجلش؛ اكتب كل عنصر في فقرة لوحده زي النموذج التعريفي بالظبط.","tb1_tr1":"السؤال بيديك مقال جاهز عن دير سانت كاترين وبيطلب منك حاجة واحدة بس: تكتب وصف خارجي للدير بأسلوبك أنت، مستعين بالنقط اللي مديهالك: برج الأجراس جواه، الجبال الشاهقة حواليه، البساتين الصغيرة، وصخور الجرانيت. يعني هتتكلم عن شكل الدير من برّه وموقعه بس، متدخلش في التفاصيل الداخلية. وافتكر إن الوصف الخارجي بيشمل الموقع والشكل العام والمساحة.","tb1_tr2":"هنا المطلوب وصف داخلي لمكتبة الإسكندرية بأسلوبك. ركز على اللي جوه المبنى بس: البهو الواسع، السقف العالي بالقبة الزجاجية، قاعات القراءة التمانية، الطاولات والكراسي وأجهزة الحاسوب، قاعة الكتب النادرة وقاعة المؤتمرات ومناطق الاستراحة. افتكر: الوصف الداخلي يعني التفاصيل والأثاث والتصميم من جوه، مش الموقع ولا الشكل من برّه.","tb1_tr3":"المطلوب هنا فقرة واحدة عن الأوصاف الحسية لواحة سيوة. الأوصاف الحسية يعني اللي بتستقبله بحواسك: شم (رائحة النخيل والتمر الناضج ورائحة المياه الكبريتية)، وسمع (حفيف أوراق النخيل وخرير المياه وأصوات العصافير والضفادع)، وبصر (النخيل الأخضر والرمال الذهبية والمياه الزرقاء)، ولمس (الرمال الناعمة). جمّع الحاجات دي في فقرة واحدة مترابطة بأسلوبك.","tb1_tr4":"المقال عن قلعة صلاح الدين خلص من غير خاتمة، والمطلوب منك تكتب خاتمة مناسبة بأسلوبك. الخاتمة الجيدة بتلخص الانطباع العام عن المكان وبتعبر عن مشاعرك تجاهه وبتسيب رسالة في نفس القارئ. افتكر جو القلعة: الجلال والهيبة والفخر بالتراث الإسلامي، وحط ده في خاتمتك.","tb1_tr5":"دي التطبيق الشامل عليك: اختار مكان من القائمة واكتب عنه مقال وصف كامل من ١٣٠ لـ ١٧٠ كلمة. الزم العناصر: مقدمة وموضوع وخاتمة، وركز على الوصف المعبر الدقيق والجو العام، وراعي التسلسل المنطقي وسلامة الإملاء والخط. نصيحة: قبل ما تكتب، جمّع أفكارك في نقط تحت كل عنصر، وبعدين حولها لفقرات مترابطة.","tb2_def":"الخطبة الإقناعية هدفها إنك تقنع الناس اللي بتسمعك بفكرة معينة، أو تخليهم ياخدوا موقف من قضية. ومش هتقدر تقنعهم بكلام وخلاص؛ لازم تجيب أدلة ومعلومات صحيحة وتستخدم أساليب مؤثرة تخلي كلامك يدخل القلب والعقل.","tb2_steps":"عشان تكتب خطبة إقناعية امشي على السبع خطوات دول: اختار موضوع يهم جمهورك، وحدد هدفك والرسالة اللي عايز توصلها، وبعدين جمّع الأدلة والبراهين اللي بتأيد فكرتك، واكتب مقدمة تخطف الانتباه من أول لحظة، وبعدين اعرض أفكارك الرئيسة واحدة واحدة ومع كل فكرة دليلها، واختم بخاتمة مناسبة، وأخيرًا راجع كلامك وحسّنه.","tb2_elems":"الخطبة الإقناعية ليها أربعة عناصر: العنوان لازم يكون معبر وجذاب زي «نحو مجتمع متقدم». المقدمة فيها التحية زي «السلام عليكم» أو «أيها الأصدقاء الأعزاء» وبعدين تعريف موجز بالموضوع وأهميته. الموضوع فيه الفكرة الأولى ودليلها، والتانية ودليلها، والتالتة ودليلها، وخد بالك: مش شرط تكون ثلاث أفكار بالظبط، ممكن أكتر أو أقل. والخاتمة فيها تلخيص الأفكار في جملة واحدة، ودعوة المستمعين للعمل والتطبيق، وجملة ختامية مؤثرة.","tb2_note":"حاجتين متهملهمش وأنت بتكتب: أولًا استخدم أساليب الإقناع زي الاستفهام والنداء والتشبيه عشان كلامك يبقى مؤثر. ثانيًا الأدلة اللي هتستعين بيها أنواعها كتير: آيات قرآنية وأحاديث نبوية وأبيات شعرية وأقوال مأثورة وحقائق علمية وإحصائيات وأمثلة من الواقع وتجارب شخصية أو تاريخية. اختار منها اللي يناسب موضوعك.","tb2_model":"النموذج ده بيعلمك شكل الخطبة الحقيقي. لاحظ بدأ بعنوان معبر «القراءة سلاح المستقبل»، وبعدين مقدمة خطفت الانتباه بإحصائية صادمة: الشباب في الدول المتقدمة بيقرأ ٥٠ كتاب في السنة واحنا بنقرأ كتابين بس! وبعدين عرض ثلاث أفكار كل واحدة بدليلها: القراءة غذاء العقل، وأعظم الشخصيات زي الجاحظ وابن خلدون كانوا قراء نهمين، والقراءة بتطور مهاراتنا اللغوية. وقفل بدعوة واضحة: ابدأوا بكتاب واحد شهريًا، وجملة مؤثرة: استثمروا في عقولكم فهي أغلى ما تملكون.","tb2_model_q":"أسئلة الفهم دي بتدربك تحلل أي خطبة. لما يسألك إزاي الخطيب جذب الانتباه، افتكر إن البداية بالإحصائيات والأرقام الصادمة أو الأسئلة من أقوى طرق جذب الانتباه. ولما يسألك عن الأفكار الرئيسة، دور على الفقرات اللي كل واحدة فيهم بتقدم فكرة ودليلها. والدعوة في الآخر هي اللي بيطلبها من المستمعين يعملوها.","tb2_tatbiq":"هنا هتكتب خطبة إقناعية كاملة عن السفر وفوائده في حياتنا. فكر معايا: السفر بيفتحلنا إيه؟ بيتعرفنا على ثقافات جديدة، وبيكسبنا خبرات وصداقات، وبيجدد نشاطنا ويريح أعصابنا. حط كل فكرة ومعاها دليلها، وابدأ بتحية ومقدمة جذابة، واختم بدعوة زملائك لاغتنام فرص السفر.","tb2_tr1":"الخطبة دي عن التنمر وجسمها موجود لكن ناقصها مقدمة وخاتمة، والمطلوب تكتبهم بأسلوبك. المقدمة لازم فيها تحية وجذب انتباه وتعريف موجز بالموضوع وأهميته. والخاتمة فيها تلخيص الأفكار ودعوة للعمل وجملة مؤثرة. مثلًا ابدأ بسؤال مؤثر عن شعور الطالب المتنمَّر عليه، واختم بدعوة الجميع لرفض التنمر ومساندة زملائهم.","tb2_tr2":"الخطبة عن فن تنظيم الوقت والمطلوب تكتب الفكرة الأولى وأدلتها. بص على بنية الخطبة: بعد المقدمة فيه أفكار مترابطة: تنظيم الوقت بيخلق وقت للأنشطة الممتعة، وبيقلل التوتر، ومهارة حياتية للمستقبل. اختار أول فكرة واكتبها ومعاها أدلتها من إحصائيات وأمثلة. وخد بالك من الأسلوب: بدأ بسؤال يجذب الانتباه «ماذا لو أخبرتكم...» وختم بحكمة «الوقت كالسيف إن لم تقطعه قطعك».","tb2_tr3":"خطبة «مهاراتك مستقبلك» والمطلوب الفكرة الثانية وأدلتها. لاحظ بنية الخطبة: مقدمة بإحصائية، وبعدين فكرة عن تنمية الذكاء وتحسين الأداء الدراسي بدليل علمي (دراسة أثبتت درجات أعلى بنسبة ٢٠٪)، وبعدين فكرة عن الثقة بالنفس والتميز، وخاتمة فيها تلخيص ودعوة عملية. الفكرة الثانية هي اللي بتتكلم عن زيادة الثقة بالنفس والتميز بين الأقران، اكتبها بأسلوبك مع أدلتها.","tb2_tr4":"خطبة «اختر صديقك بعناية» والمطلوب الفكرة الثالثة وأدلتها. الخطبة بدأت بجذب انتباه بأسئلة، والفكرة الأولى عن أثر الصديق في السلوك والأخلاق ومعاها دليل من الدراسات وحديث شريف «المرء على دين خليله فلينظر أحدكم من يخالل»، والفكرة التانية عن وقوف الأصدقاء الحقيقيين بجانبنا في أوقات الضعف والحاجة. اكتب فكرة ثالثة مناسبة بأسلوبك مع أدلة وبراهين، وزي ما الخطبة خلصت: تلخيص للأفكار ودعوة لحسن اختيار الصديق وأن تكون أنت صديقًا جيدًا.","tb2_tr5":"التطبيق الشامل للخطبة الإقناعية: اختار موضوع من الاتناشر موضوع دول واكتب خطبة كاملة من ١٣٠ لـ ١٧٠ كلمة. الزم العناصر الأربعة: عنوان معبر جذاب، مقدمة فيها تحية وتعريف بالموضوع، موضوع فيه أفكار وكل فكرة بدليلها (آية أو حديث أو إحصائية أو مثال من الواقع)، وخاتمة فيها تلخيص ودعوة للعمل وجملة مؤثرة. وراجع الإملاء والخط والتسلسل.","tbx_q1":"دي مراجعة شاملة على درس وصف المكان: مديك مجموعة جمل متلخبطة عن محمية رأس محمد ومطلوب توزع كل جملة على العنصر المناسب ليها. اسأل نفسك عن كل جملة: دي بتتكلم عن شكل المكان وموقعه من برّه؟ يبقى خارجية. عن التفاصيل اللي جواه؟ يبقى داخلية. عن حاجة بنشمها أو نسمعها أو نشوفها؟ يبقى حسية. عن إحساس المكان العام؟ يبقى الجو العام. عن حركة الناس ونشاطهم؟ يبقى مظاهر النشاط والحركة. جملة التقييم العام في الآخر؟ دي خاتمة. والجملة القصيرة الجذابة اللي بتشبه اسم المقال؟ دي العنوان.","tbx_a1":"دي الإجابة النموذجية للتصنيف. لاحظ: العنوان جملة قصيرة جذابة «لؤلؤة سيناء الساحرة». المقدمة فيها أهمية المحمية. الأوصاف الخارجية: المياه المحيطة والشواطئ والجبال. الداخلية: الأسماك والشعاب المرجانية وأشجار المنجروف. الحسية: أصوات الأمواج والطيور ورائحة الملح وتلألؤ المياه. الجو العام: الراحة والطمأنينة. النشاط والحركة: الغوص ورحلات القوارب. الخاتمة: التجربة التي لا تُنسى وضرورة المحافظة على المحمية.","tbx_q2":"دلوقتي هتبني المقال الكامل من الجمل اللي صنفتها. رتبها بالترتيب الصحيح: عنوان، مقدمة، أوصاف خارجية، داخلية، حسية، جو عام، نشاط وحركة، خاتمة، ووصّل بينها بروابط لغوية من عندك بأسلوبك زي النماذج اللي شفناها.","tbx_q3":"هنا المعادلة معكوسة: مديك جمل مبعثرة عن ترشيد استهلاك المياه ومطلوب تبني منها خطبة إقناعية مترابطة. رتبها: ابدأ بجملة التحية وجذب الانتباه (هل تعلمون أن مليار إنسان...)، وبعدين أفكار الأهمية: الماء نعمة للأجيال القادمة، وترشيده يوفر المال، والدليل الشرعي: الآية الكريمة، وبعدين الدعوة العملية: أقفلوا الصنبور وأصلحوا التسريب، واختم بالجملة المؤثرة عن قطرة الماء هدية لأطفال المستقبل. ووصّلها بأسلوبك.","tbx_q4":"خطبة ناقصة ومطلوب تكمل الفراغات. بص على اللي قبل وبعد كل فراغ عشان تعرف المطلوب: الفراغ الأول بعد التحية يبقى ده تتمة المقدمة (جذب انتباه وتعريف بخطورة التلوث). الفراغ التاني قبل الآية يبقى جملة تمهد للدليل الشرعي. الفراغات الأخيرة في الآخر دي الخاتمة: تلخيص الفكرة ودعوة للعمل بخطوات عملية وجملة مؤثرة. لاحظ المثال الياباني عن فصل النفايات ده دليل من الواقع على إن التغيير بيبدأ بخطوات صغيرة.","tbx_q5":"آخر تطبيق شامل: اختار موضوع من العشرة واكتب خطبة إقناعية كاملة من ١٣٠ لـ ١٧٠ كلمة. افتكر العناصر الأربعة: عنوان جذاب، مقدمة بتحية وجذب انتباه، موضوع بأفكار وأدلة متنوعة (آية، حديث، بيت شعر، حقيقة علمية، مثال من الواقع)، وخاتمة بتلخيص ودعوة للعمل وجملة مؤثرة. وراجع الإملاء والخط والتسلسل المنطقي."});
Array.prototype.push.apply(D.lessons,[{"id":"tb1","stage":"tabeer","title":"الدرس الأول: كتابة مقال وصف مكان","segments":[{"label":"ذاكر: وصف المكان وخطوات كتابة المقال وعناصره","explain":[{"b":"tb1_def"},{"b":"tb1_steps"},{"b":"tb1_elems"}],"questions":[{"t":"mcq","src":"أسئلة سريعة","q":"وصف المكان نصٌّ أدبيٌّ يهدف إلى:","options":["حكي قصة خيالية للقارئ","وصف مكان معين بطريقة دقيقة تجعل القارئ يتخيله ويشعر بأجوائه","إقناع المستمعين بفكرة معينة","سرد الأحداث التاريخية فقط"],"a":1,"why":["tb1_def"]},{"t":"mcq","src":"أسئلة سريعة","q":"أول خطوات كتابة مقال وصف مكان:","options":["كتابة الخاتمة","جمع التفاصيل وترتيبها","اختيار المكان الذي تريد وصفه بعناية مع التأكد من معرفتك الجيدة له","مراجعة النص"],"a":2,"why":["tb1_steps"]},{"t":"mcq","src":"أسئلة سريعة","q":"الألوان والأصوات والروائح من:","options":["الأوصاف الخارجية","الأوصاف الداخلية","الأوصاف الجسِّية","وصف مظاهر الحركة والنشاط"],"a":2,"why":["tb1_elems"]},{"t":"open","src":"أسئلة الكتاب المقرر","q":"اذكر عناصر كتابة مقال وصف مكان مع بيان دور كل عنصر.","ans":["tb1_elems"],"mod":"العنوان: جذاب ومعبر عن طبيعة المكان مثل «حديقة الأحلام». المقدمة: تعريف مختصر بالمكان وأهميته وسبب اختياره. الموضوع: ويشمل الأوصاف الخارجية (الموقع، الشكل العام، المساحة)، والأوصاف الداخلية (التفاصيل، الأثاث، التصميم)، والأوصاف الجسِّية (الألوان، الأصوات، الروائح)، ووصف الجو العام للمكان، ووصف مظاهر الحركة والنشاط فيه. الخاتمة: تلخيص الانطباع العام والمشاعر الشخصية تجاه المكان مع رسالة ختامية تترك أثرًا في نفس القارئ."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"آخر خطوة في كتابة مقال وصف مكان هي مراجعة النص للتأكد من تسلسل الأفكار ووضوح التعبير.","options":["صح","خطأ"],"a":0,"why":["tb1_steps"]}],"video":""},{"label":"النموذج التعريفي (مجاب عنه): كنز مصر الحضاري الجديد","explain":[{"b":"tb1_model"},{"b":"tb1_model_q"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"ما العنوان الذي اختاره الكاتب لمقاله؟ وما الذي يميزه؟","ans":["tb1_model_q"],"mod":"اختار الكاتب عنوان «كنز مصر الحضاري الجديد»، وما يميزه أنه عنوان جذاب؛ حيث يشير إلى قيمة المتحف الحضارية."},{"t":"open","src":"أسئلة الكتاب المقرر","q":"وضِّحْ سبب اختيار الكاتب لهذا المكان كي يصفَهُ.","ans":["tb1_model_q"],"mod":"أن المتحف يعدُّ منارة ثقافية تضيء طريق المستقبل بنور الماضي المجيد."},{"t":"open","src":"أسئلة الكتاب المقرر","q":"حدد العناصر التي اشتمل عليها الوصف الخارجي للمتحف.","ans":["tb1_model_q"],"mod":"١- مساحته أكثر من ٣٠٠ ألف متر مربع. ٢- أنه تحفة معمارية حديثة. ٣- الحدائق الشاسعة حول المتحف والتي تمتلئ بالنباتات والنخيل."},{"t":"open","src":"أسئلة الكتاب المقرر","q":"أشار الكاتب إلى بعض الأوصاف الحسية للمتحف، اذكر بعضها.","ans":["tb1_model_q"],"mod":"رائحة التاريخ المهيبة – همسات الزوار – أصوات الأقدام – الأضواء – الألوان الساحرة."},{"t":"open","src":"أسئلة الكتاب المقرر","q":"وضِّحْ بعضَ المشاعر التي يثيرها المتحف في نفوس زائريه.","ans":["tb1_model_q"],"mod":"الهيبة والجلال والدهشة والإعجاب."},{"t":"open","src":"أسئلة الكتاب المقرر","q":"ما الانطباع النهائي الذي تركه الكاتب عن المتحف في الخاتمة؟","ans":["tb1_model_q"],"mod":"أنَّ المتحف المصري الكبير رمزٌ لعظمة الحضارة المصرية."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"في نموذج «كنز مصر الحضاري الجديد» جاء وصف همسات الزائرين وأصوات أقدامهم ضمن:","options":["الأوصاف الخارجية","الأوصاف الداخلية","الأوصاف الحسِّية","الخاتمة"],"a":2,"why":["tb1_model"]}],"video":""},{"label":"النموذج التطبيقي: اكتب مقال وصف مكان","explain":[{"b":"tb1_tatbiq"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"بالاستعانة بعناصر مقال وصف المكان، اكتب مقال وصف مكان زُرتُه وأعجبك وترك فيك أثرًا لا يُنسى.","ans":["tb1_tatbiq"],"mod":"إجابة نموذجية: اكتب عنوانًا جذابًا معبرًا عن المكان، ثم مقدمة تعرِّف بالمكان وأهميته وسبب اختياره، ثم موضوعًا يشمل بالترتيب: الأوصاف الخارجية (الموقع والشكل العام والمساحة)، والأوصاف الداخلية (التفاصيل والأثاث والتصميم)، والأوصاف الحسية (الألوان والأصوات والروائح)، والجو العام للمكان وأثره في الزوار، ومظاهر الحركة والنشاط فيه، ثم خاتمة تلخص انطباعك العام ومشاعرك مع رسالة مؤثرة. راجع النص بعد الانتهاء للتأكد من تسلسل الأفكار ووضوح التعبير وسلامة الإملاء."}],"check":[],"video":""},{"label":"تدريب: دير سانت كاترين (وصف خارجي)","explain":[{"b":"tb1_tr1"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"اكتب بأسلوبك وصفًا خارجيًّا لدير سانت كاترين مستعينًا بما يلي: (بداخله برج الأجراس - يحيط به الجبال الشاهقة - البساتين الصغيرة من حوله - صخور الجرانيت المنتشرة).","ans":["tb1_tr1"],"mod":"إجابة نموذجية: يقع دير سانت كاترين على سفوح جبل سيناء في أعماق شبه جزيرة سيناء، تحيط به الجبال الشاهقة من كل جانب كأنها حراس أوفياء، وتنتشر حوله البساتين الصغيرة التي تضفي على المكان خضرة وجمالًا، وتتناثر صخور الجرانيت في محيطه، أما بداخله فيرتفع برج الأجراس شامخًا تتردد منه أصوات الأجراس في أوقات الصلاة."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"من الأوصاف الخارجية لدير سانت كاترين كما ورد في المقال:","options":["المخطوطات النادرة باللغات اليونانية","موقعه على سفوح جبل سيناء","أيقونات كنيسة التجلي","الخزائن الخشبية العتيقة"],"a":1,"why":["tb1_tr1"]}],"video":""},{"label":"تدريب: مكتبة الإسكندرية (وصف داخلي)","explain":[{"b":"tb1_tr2"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"اكتب بأسلوبك وصفًا داخليًّا لمكتبة الإسكندرية مستعينًا بما يلي: (بهو واسع - سقف عالٍ مُغطًّى بقبَّة زجاجية - ٨ قاعاتٍ للقراءة - طاولات خشبية - كراسيٌّ - أجهزة حاسوب حديثة - قاعة الكتب النادرة - قاعة المؤتمرات - مناطق استراحة للزائرين).","ans":["tb1_tr2"],"mod":"إجابة نموذجية: عند دخول مكتبة الإسكندرية يستقبلك بهو واسع يعلوه سقف عالٍ مغطًّى بقبة زجاجية يتدفق منها ضوء الشمس الطبيعي. وتضم المكتبة ثماني قاعات للقراءة رُتِّبت فيها الطاولات الخشبية والكراسي بانتظام، وتنتشر أجهزة الحاسوب الحديثة في أرجائها لخدمة الباحثين، وبجانبها قاعة الكتب النادرة التي تحفظ كنوز المخطوطات، وقاعة المؤتمرات التي تستضيف الفعاليات العلمية، ومناطق استراحة مريحة للزائرين."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"يتميز مبنى مكتبة الإسكندرية من الخارج بـ:","options":["أبراجه الدفاعية الضخمة","تصميمه الدائري الفريد الذي يشبه قرص الشمس المائل","قبته البيزنطية","جدرانه المبنية من الطوب اللِّبن"],"a":1,"why":["tb1_tr2"]}],"video":""},{"label":"تدريب: واحة سيوة (الأوصاف الحسِّية)","explain":[{"b":"tb1_tr3"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"اكتب بأسلوبك فقرةً عن الأوصاف الحسِّيَّةِ لواحة سيوة مستعينًا بالعناصر الواردة في السؤال.","ans":["tb1_tr3"],"mod":"إجابة نموذجية: في واحة سيوة تشتم رائحة النخيل المختلطة بعبق التمر الناضج، وتفوح من العيون الطبيعية رائحة المياه الكبريتية الساخنة، ويداعب سمعك حفيف أوراق النخيل مع خرير المياه الهادئ وأصوات العصافير والضفادع، وتبهر عينيك أشجار النخيل الخضراء والرمال الذهبية والمياه الزرقاء الصافية، وتداعب قدميك الرمال الناعمة؛ فتشعر وكأنك في قطعة من الجنة."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"«خرير المياه الهادئ وأصوات العصافير» من الأوصاف الحسية المتعلقة بحاسة:","options":["البصر","الشم","السمع","اللمس"],"a":2,"why":["tb1_tr3"]}],"video":""},{"label":"تدريب: قلعة صلاح الدين الأيوبي (كتابة خاتمة)","explain":[{"b":"tb1_tr4"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"اكتب بأسلوبك خاتمةً مناسبةً لمقال وصف قلعة صلاح الدين الأيوبي، موضِّحًا فيها الانطباع العام عن القلعة ومشاعرك تجاهها.","ans":["tb1_tr4"],"mod":"إجابة نموذجية: وهكذا تظل قلعة صلاح الدين الأيوبي شاهدةً على عظمة التاريخ الإسلامي وعبقرية العمارة الحربية؛ فهي ليست مجرد أسوار حجرية، بل صرح يبعث في النفس الفخر والجلال، ويترك في قلب كل زائر دهشة وإعجابًا بما صنعته أيدي المسلمين، ورسالة خالدة بأن الحضارة تُبنى بالإرادة والإيمان."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"بدأ بناء قلعة صلاح الدين الأيوبي عام:","options":["١١٧٦م","١١٨٢م","١١٧٠م","١١٩٠م"],"a":0,"why":["tb1_tr4"]}],"video":""},{"label":"تدريب المستوى الثاني: مقال وصف مكان كامل","explain":[{"b":"tb1_tr5"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"اختر أحد الأماكن الآتية: (الحديقة العامة - شاطئ البحر الذي زرته - مكتبة المدرسة - حديقة الألعاب «الملاهي» - ناديك الرياضي - مطعم العائلة المُحَبَّب - محطة القطار في مدينتك - معرض الكتاب السنوي)، ثم اكتب مقالًا لوصفه مع مراعاة عناصر المقال، على أن يتراوح عدد كلماته بين ١٣٠ و١٧٠ كلمة.","ans":["tb1_tr5","tb1_elems"],"mod":"إجابة نموذجية (خطوات الحل): ١- اختر مكانًا تعرفه جيدًا من القائمة. ٢- ضع عنوانًا جذابًا معبرًا عنه. ٣- اكتب مقدمة تعرِّف بالمكان وأهميته وسبب اختياره. ٤- اكتب الموضوع مرتبًا: الأوصاف الخارجية ثم الداخلية ثم الحسية، ثم الجو العام، ثم مظاهر الحركة والنشاط. ٥- اختم بتلخيص الانطباع العام ومشاعرك ورسالة مؤثرة. ٦- التزم بعدد الكلمات (من ١٣٠ إلى ١٧٠ كلمة)، وراجع التسلسل المنطقي والإملاء والخط."}],"check":[],"video":""}]},{"id":"tb2","stage":"tabeer","title":"الدرس الثاني: كتابة خطبة إقناعية","segments":[{"label":"ذاكر: الخطبة الإقناعية وخطواتها وعناصرها (١)","video":"","explain":[{"b":"tb2_def"},{"b":"tb2_steps"},{"b":"tb2_elems"}],"questions":[],"check":[]},{"label":"ذاكر: الخطبة الإقناعية وخطواتها وعناصرها (٢)","video":"","explain":[{"b":"tb2_note"}],"questions":[{"t":"mcq","src":"أسئلة سريعة","q":"الخطبة الإقناعية تهدف إلى:","options":["وصف مكان معين وصفًا دقيقًا","إقناع المستمعين بفكرة معينة أو دعوتهم لاتخاذ موقف محدد من قضية ما","حكي قصة للتسلية","تعليم قواعد اللغة"],"a":1,"why":["tb2_def"]},{"t":"mcq","src":"أسئلة سريعة","q":"من أساليب الإقناع الواردة بالدرس:","options":["أسلوب الاستفهام والنداء والتشبيه","التكرار الممل","الغموض المتعمد","الاختصار المخل"],"a":0,"why":["tb2_note"]},{"t":"mcq","src":"أسئلة سريعة","q":"مقدمة الخطبة الإقناعية تشمل:","options":["تلخيص الفكر الأساسية","التحية وتعريفًا بالموضوع وأهميته بشكل موجز","دعوة المستمعين للعمل","جملة ختامية مؤثرة"],"a":1,"why":["tb2_elems"]},{"t":"open","src":"أسئلة الكتاب المقرر","q":"اذكر خطوات كتابة الخطبة الإقناعية بالترتيب.","ans":["tb2_steps"],"mod":"أولًا: اختيار موضوع مناسب يهم الجمهور المستهدف. ثانيًا: تحديد الهدف من الخطبة والرسالة المراد إيصالها. ثالثًا: جمع الأدلة والبراهين المؤيدة للفكرة الأساسية. رابعًا: كتابة المقدمة الجاذبة للانتباه. خامسًا: كتابة الفِكر الرئيسة مع الأدلة والبراهين. سادسًا: كتابة خاتمة مناسبة. سابعًا: مراجعة النص وتنقيحه."},{"t":"open","src":"أسئلة الكتاب المقرر","q":"تشمل الأدلة والبراهين في الخطبة الإقناعية أنواعًا متعددة، اذكرها.","ans":["tb2_note"],"mod":"آيات قرآنية – أحاديث نبوية – أبياتًا شعرية – أقوالًا مأثورة – حقائق علمية وإحصائيات – أمثلة من الواقع – تجارب شخصية أو تاريخية."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"يشترط أن يكون عدد الفِكر في موضوع الخطبة الإقناعية ثلاثًا بالضبط.","options":["صح","خطأ"],"a":1,"why":["tb2_elems"]}]},{"label":"النموذج التعريفي (مجاب عنه): القراءة سلاح المستقبل","explain":[{"b":"tb2_model"},{"b":"tb2_model_q"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"ما العنوان الذي اختاره الكاتب للخطبة؟ وما رأيك فيه؟","ans":["tb2_model_q"],"mod":"«القراءة سلاح المستقبل»؛ يدلُّ على شدة تأثير القراءة على حياتنا في المستقبل."},{"t":"open","src":"أسئلة الكتاب المقرر","q":"كيف تمكَّنَ الخطيب من جذب انتباه المستمعين في بداية الخُطبة؟","ans":["tb2_model_q"],"mod":"من خلال الإحصائية التي ذكرها حول معدل القراءة في الدول المتقدمة ومعدلها في بلادنا."},{"t":"open","src":"أسئلة الكتاب المقرر","q":"اذكر الفِكرَ الرئيسة التي اعتمدت عليها الخطبة لترشدنا إلى أهمية القراءة.","ans":["tb2_model_q"],"mod":"القراءة غذاء العقل وتنمي القدرات الفكرية – أعظم الشخصيات كانوا قراءً نهمين – القراءة تطور المهارات اللغوية والتعبيرية."},{"t":"open","src":"أسئلة الكتاب المقرر","q":"وردتْ بالخطبة بعضُ الدلائل والبراهين التي تدلُّ على أهمية القراءة، اذكر بعضَها.","ans":["tb2_model_q"],"mod":"القراءة تنمي قدراتنا الفكرية، وتوسِّع مداركنا، وتجعلنا أكثر قدرة على فهم العالم من حولنا."},{"t":"open","src":"أسئلة الكتاب المقرر","q":"ما الدعوة التي وجهها الخطيب في النهاية؟","ans":["tb2_model_q"],"mod":"جَعْل القراءة عادة يومية والبدء بكتاب واحد شهريًّا."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"استشهد الخطيب في الفكرة الثانية بـ:","options":["إحصائية عن معدل القراءة","الجاحظ وابن خلدون كنموذجين للقراء النهمين","آية قرآنية","تجربة شخصية للكاتب"],"a":1,"why":["tb2_model"]}],"video":""},{"label":"النموذج التطبيقي: خطبة عن السَّفَر وفوائده","explain":[{"b":"tb2_tatbiq"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"بالاستعانة بعناصر الخطبة الإقناعية، اكتب خطبة إقناعية لعرضها على زملائك عن السَّفَر وفوائده في حياتنا.","ans":["tb2_tatbiq","tb2_elems"],"mod":"إجابة نموذجية (خطوات الحل): ابدأ بعنوان معبر جذاب مثل «السفر متعة وفائدة»، ثم مقدمة فيها تحية وتعريف موجز بأهمية السفر، ثم موضوع يعرض أفكارًا مثل: السفر يوسع المدارك ويتيح التعرف على ثقافات جديدة (الدليل: أمثلة من الواقع)، والسفر يكسب الخبرات ويصقل الشخصية، والسفر يجدد النشاط ويريح الأعصاب، مع دليل لكل فكرة، ثم خاتمة تلخص الفِكر وتدعو الزملاء لاغتنام فرص السفر الهادف بجملة مؤثرة."}],"check":[],"video":""},{"label":"تدريب: التنمر (كتابة مقدمة وخاتمة)","explain":[{"b":"tb2_tr1"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"اكتب مقدمةً وخاتمةً مناسبتين لخطبة «التنمر: خطر يهدد أطفالنا ومدارسنا».","ans":["tb2_tr1","tb2_elems"],"mod":"إجابة نموذجية — المقدمة: «أيها المعلمون الكرام، أيها الزملاء الأعزاء، هل شاهدتم يومًا طالبًا يجلس وحيدًا خائفًا لا يجرؤ على اللعب مع زملائه؟ هذا ما يفعله التنمر بأطفالنا كل يوم. التنمر ظاهرة خطيرة تهدد أطفالنا ومدارسنا، وتستحق منا جميعًا أن نقف لها بالمرصاد». الخاتمة: «إذن التنمر يدمر نفسية الطالب، ويضعف تحصيله الدراسي، ويفسد بيئة المدرسة كلها؛ فلنتعاون جميعًا معلمين وطلابًا على رفضه ومواجهته، ولنمد يد العون لمن يتعرض له، ولنتذكر أن المدرسة بيتنا الثاني الذي يجب أن يشعر فيه كل طالب بالأمان». "}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"مما ورد في الخطبة عن آثار التنمر:","options":["يزيد ثقة الطالب بنفسه","يفقد المتعرض له ثقته بنفسه ويصاب بالاكتئاب والقلق","يحسن الأداء الأكاديمي","يجعل المدرسة بيتًا ثانيًا محببًا"],"a":1,"why":["tb2_tr1"]}],"video":""},{"label":"تدريب: فن تنظيم الوقت (الفكرة الأولى وأدلتها)","explain":[{"b":"tb2_tr2"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"اكتب الفكرة الأولى لخطبة «فن تنظيم الوقت» مع ذكر الأدلة والبراهين المتعلقة بها.","ans":["tb2_tr2"],"mod":"إجابة نموذجية: تنظيم الوقت مفتاح النجاح والتفوق الدراسي؛ فالطلاب الناجحون لا يدرسون أكثر من زملائهم وإنما ينظمون وقتهم بشكل أفضل، وتشير الإحصائيات إلى أن ٨٠٪ من المتفوقين يقضون وقتًا أقل في المذاكرة لكنهم يحققون نتائج أفضل، والتنظيم الجيد للوقت يخلق وقتًا إضافيًّا للأنشطة الممتعة ويقلل التوتر؛ فعندما ننظم وقت الدراسة ونركز فيه ننهي المطلوب بسرعة أكبر ويتبقى لنا وقت للراحة واللعب."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"بحسب الخطبة، ٨٠٪ من المتفوقين:","options":["يدرسون ساعات أطول من زملائهم","يقضون وقتًا أقل في المذاكرة ويحققون نتائج أفضل","لا يلعبون أبدًا","يحفظون الدروس عن ظهر قلب"],"a":1,"why":["tb2_tr2"]}],"video":""},{"label":"تدريب: مهاراتك مستقبلك (الفكرة الثانية وأدلتها)","explain":[{"b":"tb2_tr3"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"اكتب الفكرة الثانية لخطبة «مهاراتك مستقبلك» مع ذكر الأدلة والبراهين المتعلقة بها.","ans":["tb2_tr3"],"mod":"إجابة نموذجية: تعلم المهارات الجديدة يزيد الثقة بالنفس ويجعلك مميزًا بين أقرانك؛ فعندما تتعلم لغة جديدة أو ترسم لوحة رائعة أو تصمم موقعًا إلكترونيًّا تشعر بالفخر بإنجازك، وهذا التميز يجعل الآخرين ينظرون إليك بإعجاب واحترام، كما أن إتقان مهارتين مختلفتين يجعل صاحبهما مرشحًا أقوى للوظائف؛ إذ يحصل على راتب أعلى بنسبة ٤٠٪ ممن يتقن مهارة واحدة، وستتطلب ٩٠٪ من الوظائف المستقبلية مهارات متعددة."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"أثبتت الدراسة العلمية الواردة بالخطبة أن الطلاب الذين يتعلمون مهارات إضافية يحصلون على درجات أعلى بنسبة:","options":["١٠٪","٢٠٪","٤٠٪","٩٠٪"],"a":1,"why":["tb2_tr3"]}],"video":""},{"label":"تدريب: اختر صديقك بعناية (الفكرة الثالثة وأدلتها)","explain":[{"b":"tb2_tr4"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"اكتب الفكرة الثالثة لخطبة «اختر صديقك بعناية» مع ذكر الأدلة والبراهين المتعلقة بها.","ans":["tb2_tr4"],"mod":"إجابة نموذجية: الصديق الجيد يساندك في أوقات الضعف والحاجة؛ فالأصدقاء الحقيقيون يقفون بجانبك عندما تحتاج إليهم، ويشجعونك على تحقيق أهدافك، ويساعدونك على تجاوز الصعوبات والتحديات، وقد قال الرسول ﷺ: «المرء على دين خليله؛ فلينظر أحدكم من يُخَالِل»، ومن هنا كان اختيار الصديق الصادق الأمين المتفوق قرارًا يؤثر في شخصيتك ومستقبلك وسعادتك."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"الدليل النبوي الوارد في خطبة «اختر صديقك بعناية» هو قوله ﷺ:","options":["«المسلم من سلم المسلمون من لسانه ويده»","«المرء على دين خليله؛ فلينظر أحدكم من يُخَالِل»","«لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه»","«خيركم من تعلم القرآن وعلمه»"],"a":1,"why":["tb2_tr4"]}],"video":""},{"label":"تدريب المستوى الثاني: خطبة إقناعية كاملة","explain":[{"b":"tb2_tr5"}],"questions":[{"t":"open","src":"أسئلة الكتاب المقرر","q":"اختر أحد الموضوعات الآتية: (الأمانة - الصدق - العدل - تعلم اللغات - التدخين - العمل التطوعي - الطعام الصحي - حسن الخلق - احترام حقوق الجيران - التلوث - تقبُّل الاختلاف - ترشيد استهلاك الماء)، ثم اكتب خطبة إقناعية حوله مع مراعاة عناصر الخطبة، بعدد كلمات بين ١٣٠ و١٧٠ كلمة.","ans":["tb2_tr5","tb2_elems"],"mod":"إجابة نموذجية (خطوات الحل): ١- اختر موضوعًا تستطيع جمع أدلة عنه. ٢- ضع عنوانًا معبرًا جذابًا. ٣- ابدأ المقدمة بتحية وجملة أو إحصائية تجذب الانتباه وتعريف بالموضوع. ٤- اعرض فكرتين أو ثلاثًا في الموضوع مع دليل لكل فكرة (آية أو حديث أو بيت شعر أو حقيقة علمية أو مثال من الواقع). ٥- اختم بتلخيص الفِكر في جملة ودعوة المستمعين للعمل وجملة مؤثرة. ٦- التزم بعدد الكلمات وراجع الإملاء والخط والتسلسل المنطقي."}],"check":[],"video":""}]},{"id":"tbx","stage":"tabeer","title":"تدريبات التعبير الكتابي الشاملة","segments":[{"label":"تصنيف جمل مقال وصف محمية رأس محمد","explain":[{"b":"tbx_q1"},{"b":"tbx_a1"}],"questions":[{"t":"mcq","src":"تدريبات شاملة","q":"جملة «محمية رأس محمد.. لؤلؤة سيناء الساحرة» تصلح لتكون:","options":["المقدمة","العنوان","الخاتمة","وصف الجو العام"],"a":1,"why":["tbx_a1"]},{"t":"mcq","src":"تدريبات شاملة","q":"«يمتزج صوت الأمواج الهادئة مع أصوات الطيور المهاجرة» من:","options":["الأوصاف الخارجية","الأوصاف الداخلية","الأوصاف الحسية","مظاهر النشاط والحركة"],"a":2,"why":["tbx_a1"]},{"t":"mcq","src":"تدريبات شاملة","q":"«يمارس الزوار رياضة الغوص لاستكشاف عالم الشعاب المرجانية» تُصنَّف ضمن:","options":["الأوصاف الحسية","وصف مظاهر النشاط والحركة","الأوصاف الداخلية","الجو العام"],"a":1,"why":["tbx_a1"]},{"t":"mcq","src":"تدريبات شاملة","q":"«تبعث أجواء المحمية في النفس الراحة والطمأنينة» تُصنَّف ضمن:","options":["الأوصاف الخارجية","الأوصاف الداخلية","الخاتمة","وصف الجو العام"],"a":3,"why":["tbx_a1"]},{"t":"open","src":"تدريبات شاملة","q":"صنِّف جمل المقال الواردة في السؤال الأول وفق عناصر مقال وصف المكان.","ans":["tbx_a1"],"mod":"العنوان: محمية رأس محمد.. لؤلؤة سيناء الساحرة. المقدمة: تعد محمية رأس محمد إحدى أهم المحميات الطبيعية في العالم. الأوصاف الخارجية: تحيط بالمحمية مياه البحر الأحمر الزرقاء الصافية من ثلاث جهات – تمتد الشواطئ الرملية البيضاء على طول السواحل المتعرجة – يحيط بالمحمية جبال سيناء الشاهقة ذات الألوان الذهبية والحمراء. الأوصاف الداخلية: تتنوع الأسماك بألوانها الزاهية وأشكالها المدهشة – تزدهر الشعاب المرجانية الملونة في أعماق المياه الدافئة – تنمو أشجار المنجروف الخضراء على ضفاف البحيرات المالحة. الأوصاف الحسية: يمتزج صوت الأمواج الهادئة مع أصوات الطيور المهاجرة – تنتشر رائحة الملح المنعشة مع عبير الأعشاب البحرية – تتلألأ المياه تحت أشعة الشمس. الجو العام: تبعث أجواء المحمية في النفس الراحة والطمأنينة. مظاهر النشاط والحركة: يمارس الزوار رياضة الغوص لاستكشاف عالم الشعاب المرجانية – يستمتع السياح برحلات القوارب الزجاجية لمشاهدة الأسماك. الخاتمة: زيارة رأس محمد تجربة لا تُنسى تبقى محفورة في الذاكرة – محمية رأس محمد كنز طبيعي يجب المحافظة عليه للأجيال القادمة."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"«زيارة رأس محمد تجربة لا تُنسى تبقى محفورة في الذاكرة» موضعها الصحيح في المقال:","options":["المقدمة","الخاتمة","العنوان","الأوصاف الحسية"],"a":1,"why":["tbx_a1"]}],"video":""},{"label":"كتابة مقال وصف محمية رأس محمد","explain":[{"b":"tbx_q2"}],"questions":[{"t":"open","src":"تدريبات شاملة","q":"بعد أن قمت بتصنيف العناصر السابقة، اكتب مقالًا لوصف محمية رأس محمد بأسلوبك.","ans":["tbx_a1","tbx_q2"],"mod":"إجابة نموذجية: «لؤلؤة سيناء الساحرة» — تعد محمية رأس محمد إحدى أهم المحميات الطبيعية في العالم، تحيط بها مياه البحر الأحمر الزرقاء الصافية من ثلاث جهات، وتمتد شواطئها الرملية البيضاء على طول السواحل المتعرجة، ويحيط بها جبال سيناء الشاهقة ذات الألوان الذهبية والحمراء. وفي أعماق مياهها الدافئة تزدهر الشعاب المرجانية الملونة، وتتنوع الأسماك بألوانها الزاهية وأشكالها المدهشة، وتنمو أشجار المنجروف الخضراء على ضفاف بحيراتها المالحة. ويمتزج صوت الأمواج الهادئة مع أصوات الطيور المهاجرة، وتنتشر رائحة الملح المنعشة مع عبير الأعشاب البحرية، وتتلألأ المياه تحت أشعة الشمس. وتبعث أجواء المحمية في النفس الراحة والطمأنينة. ويمارس الزوار رياضة الغوص لاستكشاف عالم الشعاب المرجانية، ويستمتع السياح برحلات القوارب الزجاجية لمشاهدة الأسماك. إن زيارة رأس محمد تجربة لا تُنسى تبقى محفورة في الذاكرة؛ فهي كنز طبيعي يجب المحافظة عليه للأجيال القادمة."}],"check":[],"video":""},{"label":"خطبة إقناعية: ترشيد استهلاك المياه","explain":[{"b":"tbx_q3"}],"questions":[{"t":"open","src":"تدريبات شاملة","q":"بالاستعانة بالجمل المعطاة، اكتب خطبة إقناعية حول «ترشيد استهلاك المياه».","ans":["tbx_q3"],"mod":"إجابة نموذجية: «قطرة الماء... قطرة الحياة» — أصدقائي الأعزاء، هل تعلمون أن مليار إنسان في العالم لا يجدون ماءً نظيفًا للشرب؟ إن الماء نعمة عظيمة، قال تعالى: ﴿وَجَعَلْنَا مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ﴾، وترشيد استهلاك الماء يحافظ على هذه النعمة للأجيال القادمة، كما أن ترشيد الاستهلاك يوفر المال ويقلل الفواتير. لذلك أدعوكم لإقفال الصنبور جيدًا وإصلاح أي تسريب فورًا، وتذكروا أن كل قطرة ماء نوفرها اليوم هي هدية لأطفال المستقبل."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"الدليل الشرعي المستخدم في خطبة ترشيد المياه هو قوله تعالى:","options":["﴿وَجَعَلْنَا مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ﴾","﴿وَلَا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلَاحِهَا﴾","﴿وَلَا تُسْرِفُوا إِنَّهُ لَا يُحِبُّ الْمُسْرِفِينَ﴾","﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾"],"a":0,"why":["tbx_q3"]}],"video":""},{"label":"إكمال خطبة إقناعية: حماية البيئة","explain":[{"b":"tbx_q4"}],"questions":[{"t":"open","src":"تدريبات شاملة","q":"أكمل الفراغات في الخطبة الإقناعية التي تدور حول «حماية البيئة».","ans":["tbx_q4"],"mod":"إجابة نموذجية: الفراغ الأول (تتمة المقدمة): «هل تعلمون أن الأرض التي نعيش عليها تصرخ اليوم من شدة ما ألمَّ بها؟ إنني أتحدث إليكم اليوم عن قضية تهمنا جميعًا: حماية البيئة». الفراغ الثاني (تمهيد للدليل الشرعي): «وحماية البيئة ليست اختيارًا بل واجب». الفراغ الثالث (بداية الخاتمة): «إذن، حماية البيئة مسئوليتنا جميعًا». الفراغ الرابع (دعوة عملية): «فلنحافظ على نظافة مدارسنا وشوارعنا، ولنزرع شجرة، ولنقلل من استهلاك البلاستيك»."}],"check":[{"t":"mcq","src":"أسئلة سريعة","q":"الدليل من الواقع الذي استشهدت به خطبة حماية البيئة هو تجربة:","options":["الصين في زراعة الغابات","اليابان في فصل النفايات وإعادة التدوير","أمريكا في توفير الطاقة","فرنسا في النقل النظيف"],"a":1,"why":["tbx_q4"]}],"video":""},{"label":"تطبيق شامل: خطبة إقناعية في موضوع من اختيارك","explain":[{"b":"tbx_q5"}],"questions":[{"t":"open","src":"تدريبات شاملة","q":"اختر أحد الموضوعات الآتية: (الثقة بالنفس - الصبر والمثابرة - التواضع وعدم الغرور - التحكم في الغضب - التعامل مع ضغوط الامتحانات - التغذية السليمة - الهواتف الذكية وتأثيرها على الطلاب - مخاطر الإنترنت وكيفية تجنبها - أهمية إعادة التدوير - الفقر وسبل مكافحته)، ثم اكتب خطبة إقناعية حوله بين ١٣٠ و١٧٠ كلمة.","ans":["tbx_q5","tb2_elems"],"mod":"إجابة نموذجية (خطوات الحل): اختر موضوعًا، وضع له عنوانًا جذابًا، وابدأ بمقدمة فيها تحية وجملة تجذب الانتباه، ثم اعرض فكرتين أو ثلاثًا مع دليل لكل منها (آية، حديث، بيت شعر، حقيقة علمية أو إحصائية، مثال من الواقع أو تجربة تاريخية)، واختم بتلخيص الفِكر ودعوة المستمعين للعمل بجملة مؤثرة، مع الالتزام بعدد الكلمات وسلامة الإملاء والخط والتسلسل المنطقي."}],"check":[],"video":""}]}]);
})();
